INSERT OR REPLACE INTO courses (id,title_zh,title_en,description_zh,description_en,icon,level,lessons,is_free,sort_order,status) VALUES (2,'耶稣生平','Life of Jesus','走过福音书，发现基督的生活和教导。','Walk through the Gospels and discover the life and teachings of Christ.','✝️','中级','8',1,1,1);
