INSERT OR REPLACE INTO courses (id,title_zh,title_en,description_zh,description_en,icon,level,lessons,is_free,sort_order,status) VALUES (4,'宣教与传福音','Missions & Evangelism','为完成大使命、分享福音预备你的心。','Prepare your heart to fulfill the Great Commission and share the Gospel.','🌍','所有级别','6',1,3,1);
INSERT OR REPLACE INTO carousel_verses (id,title_en,title_zh,content_en,content_zh,image,sort_order,status) VALUES (16,'Matthew 6:34','马太福音 6:34','"Therefore do not be anxious about tomorrow, for tomorrow will be anxious for itself. Sufficient for the day is its own trouble."','「所以，不要为明天忧虑，因为明天自有明天的忧虑；一天的难处一天当就够了。」','',0,1);
INSERT OR REPLACE INTO carousel_verses (id,title_en,title_zh,content_en,content_zh,image,sort_order,status) VALUES (17,'Joshua 1:9','约书亚记 1:9','"Have I not commanded you? Be strong and courageous. Do not be frightened, and do not be dismayed, for the Lord your God is with you wherever you go."','「我岂没有吩咐你吗？你当刚强壮胆！不要惧怕，也不要惊惶；因为你无论往哪里去，耶和华你的神必与你同在。」','',0,1);
INSERT OR REPLACE INTO carousel_verses (id,title_en,title_zh,content_en,content_zh,image,sort_order,status) VALUES (2,'Psalm 23:1-3','诗篇 23:1-3','"The Lord is my shepherd; I shall not want. He makes me lie down in green pastures. He leads me beside still waters. He restores my soul."','「耶和华是我的牧者，我必不至缺乏。他使我躺卧在青草地上，领我在可安歇的水边。他使我的灵魂苏醒。」','',1,1);
INSERT OR REPLACE INTO carousel_verses (id,title_en,title_zh,content_en,content_zh,image,sort_order,status) VALUES (3,'Philippians 4:13','腓立比书 4:13','"I can do all things through him who strengthens me."','「我靠着那加给我力量的，凡事都能做。」','',2,1);
INSERT OR REPLACE INTO carousel_verses (id,title_en,title_zh,content_en,content_zh,image,sort_order,status) VALUES (4,'Psalm 46:10','诗篇 46:10','"Be still, and know that I am God. I will be exalted among the nations, I will be exalted in the earth!"','「你们要休息，要知道我是神！我必在外邦中被尊崇，在遍地上也被尊崇。」','',3,1);
INSERT OR REPLACE INTO carousel_verses (id,title_en,title_zh,content_en,content_zh,image,sort_order,status) VALUES (5,'Isaiah 40:31','以赛亚书 40:31','"But they who wait for the Lord shall renew their strength; they shall mount up with wings like eagles; they shall run and not be weary; they shall walk and not faint."','「但那等候耶和华的，必从新得力。他们必如鹰展翅上腾，他们奔跑却不困倦，行走却不疲乏。」','',4,1);
INSERT OR REPLACE INTO carousel_verses (id,title_en,title_zh,content_en,content_zh,image,sort_order,status) VALUES (6,'Lamentations 3:22-23','耶利米哀歌 3:22-23','"The steadfast love of the Lord never ceases; his mercies never come to an end; they are new every morning; great is your faithfulness."','「我们不至消灭，是出于耶和华诸般的慈爱，是因他的怜悯不至断绝。每早晨这都是新的。你的诚实极其广大！」','',5,1);
INSERT OR REPLACE INTO carousel_verses (id,title_en,title_zh,content_en,content_zh,image,sort_order,status) VALUES (7,'Proverbs 3:5-6','箴言 3:5-6','"Trust in the Lord with all your heart, and do not lean on your own understanding. In all your ways acknowledge him, and he will make straight your paths."','「你要专心仰赖耶和华，不可倚靠自己的聪明，在你一切所行的事上都要认定他，他必指引你的路。」','',6,1);
INSERT OR REPLACE INTO vision (id,title_zh,title_en,content_zh,content_en) VALUES (1,'全球异象','Global Vision','今天，中国正在以前所未有的姿态全面影响着整个世界——无论是在经济巨浪、科技创新还是文化输出的各个领域，全球都无法忽视这股力量。然而，在属灵与宗教的版图上，世界往往只能看到一片迷雾。你或许常常听到外界的论调，认为这里是一片无神论的荒漠，或者只能看到福音事工在这里所面对的重重限制、围墙与极大的不易。是的，在这片土地上开展福音工作绝非易事。但纵观圣经救赎史，当神的子民在旷野中面对最严苛的逼迫与试炼时，往往正是万军之耶和华要在危机中掀起历史性大复兴的开端！在这里，有无数在大逼迫中淬炼出大信心的基督徒；在这里，有无数家庭教会已经传承了超过三代人，他们的信仰不是温室里的花朵，而是从烈火中走出来的精金。在这场波澜壮阔的现代复兴运动中，中国的基督徒正在圣灵的膏沐中站立起来——我们不仅在这片土地上守望服侍，更被差遣走向列国列邦，在全地所有的领域中深扎、渗透，预备将天国的荣耀带下！

出埃及记 1:12 —— 只是越发苦害他们，他们越发多起来，越发蔓延开来。

国度策略：
我们的宣教不仅发生在教堂的围墙之内，更发生在时代的各行各业之中。面对新一代的年轻人，我们核心的国度策略是：在职场与商业的第一线，建立完全属于天国的文化与生命样式。

马太福音 5:14-16 —— 你们是世上的光。城造在山上是不能隐藏的……你们的光也当这样照在人前，叫他们看见你们的好行为，便将荣耀归给你们在天上的父。

在职场中，我们通过卓越的专业能力、公义的商业诚实、以及活泼的见证故事，成为世界的光与盐。我们要进入文化的上游，在科技、创意、和产业的赛道上开疆拓土，用天国的价值观去夺回、去影响、去塑造正在迷失的新一代年轻人，让职场成为宣教的第一宣教工场。

行动：
代祷合一与财务互助

祭坛上的合一： 
我们要在教会与团契的深层代祷中保持高度合一，打破地域的局限，不断在祭坛前寻求神对于跨国宣教与技术赋能的最新时代带领。
财务上的互助： 
我们要建立坚固的国度供求与奉献网络，在财务、物资和供应链资源上，去全力支持、安慰、帮助那些在患难、逼迫和缺乏中的弟兄姊妹。用实实在在的国度相爱，见证那不可震动的国。','Today, China is impacting the entire world with an unprecedented posture—whether in the waves of economic giants, technological innovation, or cultural output, the global stage cannot ignore this powerful force. However, on the spiritual and religious landscape, the world often sees nothing but a thick mist. You may frequently hear global narratives painting this land as an atheistic desert, or focusing solely on the heavy restrictions, walls, and immense hardships faced by gospel ministries here.
Yes, carrying out gospel work in this land is by no means easy. Yet, throughout the history of biblical redemption, whenever God''s people faced the most severe oppression and trials in the wilderness, it was precisely then that the Lord of Hosts was about to launch a historic and massive revival amidst the crisis! Here, there are countless Christians whose great faith has been refined through great persecution; here, there are thousands of house churches that have stood faithfully for over three generations. Their faith is not a flower grown in a greenhouse, but pure gold refined in the blazing furnace. In this magnificent modern revival movement, Chinese Christians are standing up under the anointing of the Holy Spirit—we are not only watching and serving in this land, but are being sent forth to the nations, deeply rooting and penetrating every sphere of the earth, preparing to bring down the glory of the Kingdom!

Exodus 1:12 — But the more they were oppressed, the more they multiplied and the more they spread abroad.

Kingdom Strategy:
Our mission does not just take place within the walls of a church building, but within the very marketplace of our generation. Facing the new generation of young people, our core Kingdom strategy is: to establish the culture and life patterns that fully belong to the Kingdom of Heaven at the very frontlines of the Marketplace and commerce.

Matthew 5:14-16 — “You are the light of the world. A city set on a hill cannot be hidden... In the same way, let your light shine before others, so that they may see your good works and give glory to your Father who is in heaven.”

In the marketplace, we become the salt and light of the world through exceptional professional excellence, righteous commercial integrity, and living stories of testimony. We must enter the upstream of culture, pioneering in the tracks of technology, creativity, and industry. By leveraging Kingdom values, we aim to reclaim, impact, and shape the drifting younger generation, turning the marketplace into the primary mission field.

Action: 
Unity in Prayer & Financial Mutual Aid

Unity at the Altar: 
We must maintain a high level of unity in the deep intercession of churches and fellowships, breaking down geographical limitations, and continuously seeking the Lord’s latest timely guidance for cross-border missions and technological empowerment before the altar.

Mutual Aid in Finance: 
We must build a solid network of Kingdom supply, demand, and offering. We will fully support, comfort, and help brothers and sisters facing trials, persecution, and lack by sharing financial, material, and supply chain resources. Through practical, tangible Kingdom love, we shall bear witness to that unshakable Kingdom.');